def test_every_answer_is_the_baselines() -> None:
    check(sorted(CASES) == sorted(GOLDEN), "every measured case is asserted, and nothing else")
    for label, spec in CASES.items():
        for holder in (m, t):
            got = run(holder, spec)
            check(got == GOLDEN[label], f"{label} ({holder.__name__}): the baseline's answer, every call in order: {got}")


def test_the_rules_hold_in_the_measured_record() -> None:
    def result(label):
        return GOLDEN[label]["result"]

    def seams(label):
        return [c[0] for c in GOLDEN[label]["calls"]]

    def rows(layout):
        if "Widgets" not in layout:
            return [1]
        if layout["Orientation"] == "Horizontal":
            return [len(layout["Widgets"])]
        return [len(r["Widgets"]) if "Widgets" in r else 1 for r in layout["Widgets"]]

    leaf = {"Command": "", "SessionRestoreId": 0, "WorkingDirectory": ""}
    check(result("the layout for 0 roles") == result("the layout for 1 roles") == leaf
          and [rows(result(f"the layout for {n} roles")) for n in (2, 3)] == [[2], [3]]
          and seams("the layout for 3 roles")[-1] == "_single_row_layout_payload" and seams("the layout for 4 roles")[-1] == "_row_major_grid_layout_payload",
          "one leaf alone; a single row through three roles; a grid from four")
    check([rows(result(f"the layout for {n} roles")) for n in (4, 5, 7, 10, 13, 16)]
          == [[2, 2], [3, 2], [3, 2, 2], [3, 3, 2, 2], [3, 3, 3, 2, 2], [3, 3, 3, 3, 2, 2]],
          "the grid: ceil(n / 3) rows, as even as the count allows, the longer rows first")
    check(GOLDEN["the layout for 4 roles"]["json"].startswith('{"Orientation": "Vertical", "Widgets": [{"Orientation": "Horizontal", "Widgets": [{"Command": "", "SessionRestoreId": 0, "WorkingDirectory": ""}')
          and all(GOLDEN[k].get("type") == ("list" if k.startswith("the leaves for") else "tuple" if "list," in k or "reads the current" in k else "dict") for k in GOLDEN),
          "the exact serialization, key order included, and each result's container type")
    check(all(GOLDEN[k]["equals its JSON round trip"] is (not k.startswith("the legacy recogniser")) for k in GOLDEN if "equals its JSON round trip" in GOLDEN[k]),
          "every layout equals its own JSON round trip, so one read back from disk is recognised (the recogniser's list itself is a tuple)")
    check(result("a single row of 0 leaves") == leaf and rows(result("a single row of 5 leaves")) == [5]
          and result("a row-major grid of 1 leaves")["WorkingDirectory"] == "/w/0" and rows(result("a row-major grid of 3 leaves")) == [3],
          "a single row of any length; a grid of one row is that row, of one leaf that leaf")
    check(rows(result("the single-row threshold rebound on the launcher")) == [5] and seams("the single-row threshold rebound to none")[-1] == "_row_major_grid_layout_payload"
          and rows(result("the panes per row rebound on the launcher")) == [4, 4] and rows(result("the panes per row rebound, the grid alone")) == [2, 2, 2, 2, 1],
          "both thresholds are the launcher's when the builders run")
    check(result("the leaves rebound on the launcher")["Widgets"][0]["Widgets"][0] == {"leaf": 0} and result("the single row rebound on the launcher") == {"row": 2}
          and result("the grid rebound on the launcher") == {"grid": 7},
          "the leaves, the single row and the grid are the launcher's when the builder runs")
    check(result("the legacy recogniser's list, four roles")[0] == result("the layout for 4 roles")
          and result("the legacy recogniser's list, seven roles")[0] == result("the layout for 7 roles")
          and result("the legacy recogniser reads the current builder through the launcher")[0] == {"current": 4},
          "the legacy recogniser's first known layout is the current builder's, read through the launcher")


def test_every_launcher_seam_is_reached() -> None:
    # Every function the builders read is a recorder on the launcher (the builders themselves included); the two
    # thresholds are rebound there by their own cases, and change the layout.
    names = {name for reads in SEAMS.values() for name in reads}
    constants = {name for name in names if not callable(getattr(t, name))}
    check((names - constants) | set(FUNCTIONS) <= REACHED, f"a recorder on the launcher reached every function: missing {sorted((names - constants) | set(FUNCTIONS) - REACHED)}")
    rebound = {name for spec in CASES.values() for name in spec.get("launcher", {})}
    check(constants == {"NEW_PROJECT_SINGLE_ROW_LAYOUT_MAX_ROLES", "NEW_PROJECT_GRID_PANES_PER_ROW"} and constants <= rebound,
          f"and both thresholds rebound: {sorted(constants)} {sorted(rebound)}")


STRUCTURE = ("test_the_module_loads_only_where_its_defaults_come_from", "test_either_import_order_gives_one_set_of_objects_and_no_defaults",
             "test_the_seams_read_through_the_launcher_and_nothing_bound", "test_the_launcher_reexports_the_six_and_its_readers_reach_them_there")
LAST = ("test_every_launcher_seam_is_reached",)


def main() -> int:
    names = sorted(name for name, value in globals().items() if name.startswith("test_") and callable(value))
    for name in [*STRUCTURE, *(name for name in names if name not in STRUCTURE + LAST), *LAST]:
        globals()[name]()
    print(f"project_layouts_boundary_test: {CHECKS} checks ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
